module traffic_light
    (
      input rst_n, 
      input clk,
      input pass_request,
      output wire[7:0]clock,
      output reg[2:0]red,
      output reg[2:0]yellow,
      output reg[2:0]green
    );

	parameter idle = 3'd0;
	parameter s1_red = 3'd1;
	parameter s2_yellow = 3'd2;
	parameter s3_green = 3'd3;

	reg[2:0]state;
	reg[3:0]cnt;
	reg p_red,p_green,p_yellow;

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			state = idle;
			p_red = 1'b0;
			p_green = 1'b0;
			p_yellow = 1'b0;
		end
		else case(state)
			idle:begin
				p_red = 1'b0;
				p_green = 1'b0;
				p_yellow = 1'b0;
				state = s1_red;
			end
			s1_red:begin
				p_red = 1'b1;
				p_green = 1'b0;
				p_yellow = 1'b0;
				if (cnt == 3)begin
					state = s3_green;
				end
				else begin
					state = s1_red;
				end
			end
			s2_yellow:begin
				p_red = 1'b0;
				p_green = 1'b0;
				p_yellow = 1'b1;
				if (cnt == 3)begin
					state = s1_red;
				end
				else begin
					state = s2_yellow;
				end
			end
			s3_green:begin
				p_red = 1'b0;
				p_green = 1'b1;
				p_yellow = 1'b0;
				if (cnt == 3)begin
					state = s2_yellow;
				end
				else begin
					state = s3_green;
				end
			end
		endcase
	end

 	always @(posedge clk or negedge rst_n) begin
		if(!rst_n)begin
			cnt = 4'd10;
		end
		else if (pass_request && green && (cnt > 10))begin
			cnt = 4'd10;
		end
		else if (!green && p_green)begin
			cnt = 4'd60;
		end
		else if (!yellow && p_yellow)begin
			cnt = 4'd5;
		end
		else if (!red && p_red)begin
			cnt = 4'd10;
		end
		else begin
			cnt = cnt -1;
		end
	end

 	assign clock = cnt;
	assign red = p_red;
	assign yellow = p_yellow;
	assign green = p_green;
endmodule
